// Independent assessment questions. Lesson quick checks are deliberately not reused.
// Each module has three distinct questions per difficulty; no generated paraphrase fallback.
const q = (lessonId, difficulty, prompt, options, correctIndex, explanation) => ({ lessonId, difficulty, type: 'single', prompt, options, correctIndex, explanation })
const n = (lessonId, difficulty, prompt, answer, unit, explanation, tolerance = 0.01) => ({ lessonId, difficulty, type: 'number', prompt, answer, unit, explanation, tolerance })
const m = (lessonId, difficulty, prompt, options, correctIndices, explanation) => ({ lessonId, difficulty, type: 'multiple', prompt, options, correctIndices, explanation })

